export function BackgroundRefresh({
  refreshing = {{refreshing}},
  lastUpdated = "{{lastUpdated}}",
  duration = {{duration}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 8 }}>
        <strong>Live prices</strong>
        {refreshing && (
          <span role="status" aria-live="polite" className="spin" style={{ width: 14, height: 14, border: "2px solid #24143022", borderTopColor: accent, borderRadius: 999, display: "inline-block" }}>
            <span style={{ position: "absolute", width: 1, height: 1, overflow: "hidden" }}>Refreshing&hellip;</span>
          </span>
        )}
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", padding: "6px 0", borderTop: "1px solid #24143014", fontSize: 13 }}><span>BTC</span><span>&pound;41,204</span></div>
      <div style={{ display: "flex", justifyContent: "space-between", padding: "6px 0", borderTop: "1px solid #24143014", fontSize: 13 }}><span>ETH</span><span>&pound;2,318</span></div>
      <p style={{ margin: "10px 0 0", fontSize: 12, color: "#241430aa" }}>{lastUpdated} &mdash; the list stays interactive while data updates underneath</p>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .spin { animation: lod-bgr-spin ${duration}ms linear infinite; }
          @keyframes lod-bgr-spin { to { transform: rotate(360deg); } }
        }
      `}</style>
    </div>
  );
}
